#include <bits/stdc++.h>
using namespace std;
using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    multiset<ll> st;
    // 读入初始能量值
    for (int i = 0; i < n; ++i) {
        ll c;
        cin >> c;
        st.insert(c);
    }
    // 依次处理每次强化操作
    for (int j = 0; j < m; ++j) {
        ll v;
        cin >> v;
        // 取出最小值
        ll cur_min = *st.begin();
        st.erase(st.begin());
        ll new_val = cur_min + v;
        st.insert(new_val);
        // 输出当前最大值（multiset 中最大元素在末尾）
        cout << *st.rbegin() << "\n";
    }
    return 0;
}
